/// Run every enabled rule over one file.
///
/// Node rules fire once per node of their kind (in source order via the
/// pre-order `descendants()` walk); file rules fire once each, receiving
/// the lazy [`SemanticModel`] (which node rules never touch).
pub fn run_rules(
    rules: &[Box<dyn Rule>],
    tree: &SyntaxNode,
    model: &SemanticModel,
    config: &LintConfig,
    source: &str,
    diags: &mut Vec<Diagnostic>,
) {
    for rule in rules {
        if !config.is_enabled(rule.code()) {
            continue;
        }
        match rule.node_kind() {
            Some(kind) => {
                for node in tree.descendants() {
                    if node.kind() == kind {
                        rule.check_node(node, source, diags);
                    }
                }
            }
            None => rule.check_file(model, config, diags),
        }
    }
}
